from lib import *
S = SS('t29')
steps = [
    step("长事务让 undo 越积越多,也让它自己的快照读越来越慢。A 开一个一致性快照事务(START TRANSACTION WITH CONSISTENT SNAPSHOT,读到 v = 0 之后就闲着),别的会话给同一行更新 6 万次(每 100 次提交一次)。History list length(没清理的 undo 日志单位,每个提交的事务一个)从 38 涨到 188、338、488、638。A 再读同一行,读到的还是快照里的旧值 0,单次耗时中位数 13.46 ms——它要顺着 6 万个版本的 undo 链往回找;新会话读同一行是 60000,0.04 ms。A 提交之后 purge 线程把 undo 清掉,History list length 回到 1,用了 49.1 s;A 再读同一行(新快照)恢复到 0.05 ms。长事务按住的不只是自己,还有整条 undo 链。", t=tl(S(1)), mark=lidx(S(1), 'A 的快照读同一行'), done=lidx(S(1), 'A 提交之后', 'A 提交后再读'), b=bars([['长事务的快照读 ms', 13.46, '13.46'], ['新会话读同一行 ms', 0.04, '0.04'], ['History list length', 638, '638'], ['提交后 purge 用时 s', 49.1, '49.1']], 640, mark=[0], done=[1], cur=[2, 3]), kv=KV([['长事务的快照读', '13.46 ms,新会话 0.04 ms'], ['History list length', '38 → 638'], ['提交之后', 'purge 清完用了 49.1 s']], ['长事务的快照读'])),
    step("长事务持有的行锁让别人等。A 更新 id=1 之后迟迟不提交;B 把 innodb_lock_wait_timeout 调成 1 秒,先改 id=2(成功),再去改被 A 锁住的 id=1:等了 1005 ms 后报错 1205 Lock wait timeout exceeded。超时之后 B 的事务还开着(innodb_trx 里有它的记录),B 自己读 id=2 是 200——第一条 UPDATE 还在事务里,没有被回滚:默认只回滚超时的那一条语句,不回滚整个事务。如果应用只捕获了异常、没有 ROLLBACK 就继续往下走并最终 COMMIT,这半截修改就被提交了,库里 id=2 = 200,而本该和 id=1 的修改一起成功或一起失败。", t=tl(S(2)), mark=lidx(S(2), '等了 1005 ms', '如果应用只是捕获了异常'), done=lidx(S(2), '超时之后 B 这个事务还开着吗'), b=bars([['B 等锁超时 ms', 1005, '1005'], ['超时后 B 的事务是否还开着', 1, '是(innodb_trx 里有 1 条)'], ['半截修改提交后库里 id=2', 200, '200(id=1 没改成)']], 1005, mark=[0, 2], cur=[1]), kv=KV([['超时只回滚那一条语句', '事务还开着'], ['应用没 ROLLBACK 就 COMMIT', '提交了半截修改'], ['要求', '捕获超时后必须显式 ROLLBACK']], ['要求'])),
    step("长事务和 DDL。A 开着事务读了一下表 t(拿着元数据锁),B 执行 ALTER TABLE 要等 A;B 在等的时候,后来的普通 SELECT 也被排在 B 后面一起卡住。1.5 秒时 processlist 里有两个会话(线程 256、257)都在 Waiting for table metadata lock。A 提交之后:ALTER 用了 2.03 s 才完成(其中 2 秒是在等 A),后来那个本身只要零点几毫秒的普通 SELECT 用了 1.72 s——它在 ALTER 后面排了队。一个长事务可以通过一个排队的 DDL 把整张表的所有查询卡住。", t=tl(S(3)), mark=lidx(S(3), '1.5 秒时 processlist'), done=lidx(S(3), 'A 提交(事务结束)之后'), b=bars([['ALTER 等待 s', 2.03, '2.03'], ['后来的普通 SELECT 耗时 s', 1.72, '1.72'], ['在等元数据锁的会话数', 2, '2']], 2.1, mark=[0, 1], cur=[2]), kv=KV([['A 拿着元数据锁', '事务不结束就不放'], ['ALTER', '排队等 A'], ['后来的 SELECT', '排在 ALTER 后面一起卡 1.72 s']], ['后来的 SELECT'])),
    step("PostgreSQL 的长事务。会话 X 开 REPEATABLE READ 事务、读一次之后闲着(idle in transaction)按住快照;别的会话把 churn 表(5000 行)整体 UPDATE 了 5 次,然后 VACUUM:0 个元组被回收,30000 个里有 25000 个“已死但还不能删”(removable cutoff 732)。把 X 断开之后再 VACUUM:25000 个元组被清掉,剩 5000,0 个不能删(cutoff 737)。设置 idle_in_transaction_session_timeout = 700ms 的会话,事务里闲了 1.2 秒再用它,服务器已经把它断开:IdleInTransactionSessionTimeout。给闲置事务设一个超时,服务器自己会替你清理。", t=tl(S(4)), mark=lidx(S(4), '25000 are dead but not yet removable'), done=lidx(S(4), '25000 removed', 'IdleInTransactionSessionTimeout'), b=bars([['X 在时:不能回收的死元组', 25000, '25000'], ['X 断开后:不能回收的死元组', 0, '0'], ['X 断开后:被清掉的死元组', 25000, '25000']], 25000, mark=[0], done=[1], cur=[2]), kv=KV([['idle in transaction', '按住快照,死元组清不掉'], ['断开之后', 'VACUUM 清掉 25000 个'], ['idle_in_transaction_session_timeout', '服务器自动断开闲置事务']], ['idle_in_transaction_session_timeout'])),
    step("找出并处理长事务:监控查询 information_schema.innodb_trx(事务开始超过 N 秒的),watchdog 对超过 1.5 秒的事务 KILL。20 个事务里有 5 个故意拖 3 秒才提交:15 个提交成功,5 个被 watchdog 中断(记录里线程号、事务年龄 1.59 s、已修改 1 行);库里 w 表只有 15 行,全是 fast 的——被杀事务的修改随连接断开一起回滚。只按开了多久杀事务会误伤合法的慢事务(比如批处理),阈值、白名单和告警要按业务定。", t=tl(S(5)), mark=lidx(S(5), '20 个事务'), done=lidx(S(5), '库里 w 表有 15 行'), b=bars([['提交成功的事务', 15, '15'], ['被 watchdog 中断的事务', 5, '5'], ['库里 w 表的行数', 15, '15']], 20, done=[0, 2], mark=[1]), kv=KV([['监控查询', 'innodb_trx 里事务年龄 > 1.5 s'], ['处理', 'KILL,被杀事务的修改回滚'], ['要小心', '误伤合法的慢事务']], ['要小心'])),
]
A = mkartt('t29', 29, '分布式事务,长事务,undo,元数据锁,MySQL,PostgreSQL,idle in transaction,真实验证,动画演示',
    '实测长事务的代价:MySQL 一致性快照事务让同一行 6 万次更新后它自己的快照读变成 13.46 ms(新会话 0.04 ms),purge 清完用 49.1 s;行锁超时只回滚那条语句,应用没 ROLLBACK 会提交半截修改;持有元数据锁的事务让 ALTER 和后来的普通 SELECT 一起卡 1.72 s;PostgreSQL idle in transaction 让 25000 个死元组清不掉,idle_in_transaction_session_timeout 能让服务器断开它;watchdog 杀掉 5 个超时事务。',
    '分布式事务里到处是“事务开着不结束”的隐患:全局事务超时、悬挂、客户端崩溃。长事务在数据库本身会造成什么?undo 积压、锁等待、DDL 排队、死元组清不掉。这篇用真实的 MySQL 和 PostgreSQL 把这些后果逐个量出来,并给出监控和自动处理的办法。',
    [('13.46 ms vs 0.04 ms', '长事务的快照读与新会话读同一行(这一行被更新了 6 万次)的耗时'), ('1.72 s', '一个长事务 + 排队的 ALTER 把后来本只要零点几毫秒的普通 SELECT 卡住的时间'), ('25000 → 0', 'PostgreSQL 里 idle in transaction 会话在时 VACUUM 清不掉的死元组数 → 会话断开后')],
    [('undo 积压与快照读变慢', '<p>长事务的快照要保留旧版本,别人的更新让 undo 链越来越长,它自己的读要沿链回溯;提交后 purge 才能清理。</p>'),
     ('行锁与超时', '<p>长事务持有的行锁让别人等到超时;MySQL 默认只回滚超时的那条语句,事务本身还开着,应用必须显式 ROLLBACK。</p>'),
     ('元数据锁排队', '<p>长事务让 ALTER TABLE 等待,而等待中的 DDL 又让后来的普通查询排在它后面。</p>'),
     ('PostgreSQL 的闲置事务', '<p>idle in transaction 按住快照,VACUUM 清不掉死元组;idle_in_transaction_session_timeout 让服务器自己断开它。</p>'),
     ('监控与处理', '<p>用 innodb_trx 找出超过阈值的事务,watchdog 杀掉;阈值与白名单按业务定。</p>')],
    steps,
    [ENV_T + '。本篇用一个 MySQL 26.7.0 实例(InnoDB,默认 REPEATABLE-READ;第二节会话里把 innodb_lock_wait_timeout 调成 1 秒)和一个 PostgreSQL 16.15 实例(autovacuum 关闭,手动 VACUUM VERBOSE);第四节里 X 被断开用的是 pg_terminate_backend,真正由 idle_in_transaction_session_timeout 触发的断开在后一个小实验里单独验证;watchdog 是我写的一个线程,每 0.2 秒查一次 innodb_trx',
     '没有验证:innodb_rollback_on_timeout=ON(需要启动参数)时整个事务回滚的行为;MySQL 的 purge 速度参数(innodb_purge_threads 等)对 49.1 s 的影响;在线 DDL(ALGORITHM=INPLACE / INSTANT)对元数据锁排队的缓解;PostgreSQL 的 hot_standby_feedback 与复制槽对 VACUUM 的影响;分布式事务里“全局事务超时”与本地长事务的关系(第 22 篇);History list length 的数字取自 SHOW ENGINE INNODB STATUS,不同版本口径可能不同'],
    '长事务')
